{modal.type==='user'&&<form onSubmit={e=>{e.preventDefault();const f:any=Object.fromEntries(new FormData(e.currentTarget));action('user',{...f,id:modal.record.id,active:f.active==='on'},()=>setModal(null))}}><Field label="Full name"><input required name="name" defaultValue={modal.record.name}/></Field><Field label="Google sign-in email"><input required type="email" name="email" readOnly={!!modal.record.id} defaultValue={modal.record.email}/></Field><Field label="Role"><select name="role" defaultValue={modal.record.role||'Viewer'}>{roles.map(r=><option key={r}>{r}</option>)}</select></Field>{modal.record.id&&<label className="checkbox"><input name="active" type="checkbox" defaultChecked={!!modal.record.active}/>Active staff access</label>}<p className="muted">The staff member must sign in with this exact Google email address.</p><div className="modal-footer"><button className="btn primary" disabled={busy}>Save staff access</button></div></form>}
