function scan(e:React.FormEvent){e.preventDefault();const normalized=code.trim().toUpperCase();if(!normalized)return;if(type!=='label'&&!artisan){setFeedback({bad:true,text:'Select an artisan before scanning.'});return;}if(manual&&!verified){setFeedback({bad:true,text:'Verify the physical identity before manual entry.'});return;}const p=d.pieces.find((p:any)=>p.code===normalized),error=lines.some(p=>p.code===normalized)?`${normalized} is already in this draft. Count unchanged.`:scanError(p,type,artisan,rework);if(error)setFeedback({bad:true,text:error});else {setLines(prev=>[...prev,{...p,outcome:'',manual}]);setFeedback({text:`${p.code} added · ${lines.length+1} ${lines.length?'pieces':'piece'} scanned`});}setCode('');input.current?.focus();setVerified(false);setReview(false);setRequestKey(crypto.randomUUID());}
