function StockDetail({check,observations,action,can,busy}:any){const [code,setCode]=useState(''),[feedback,setFeedback]=useState(''),[closing,setClosing]=useState(false);const expected=JSON.parse(check.expected),seen=observations.filter((o:any)=>o.check_id===check.id),missing=expected.filter((p:any)=>!seen.some((o:any)=>o.code===p.code)),unexpected=seen.filter((o:any)=>o.result==='UNEXPECTED');const rows=[...expected.map((p:any)=>({...p,result:missing.some((m:any)=>m.id===p.id)?'MISSING':'EXPECTED'})),...unexpected];return <><h3>{check.name}</h3><div className="receipt-stats">{[['Expected',expected.length],['Counted',seen.filter((o:any)=>o.result==='EXPECTED').length],['Missing',missing.length],['Unexpected',unexpected.length]].map(([n,v])=><div key={String(n)}><small>{n}</small><b>{v}</b></div>)}</div>{check.status==='OPEN'&&<form onSubmit={async e=>{e.preventDefault();const r=await action('observe',{id:check.id,code});if(r){setFeedback(`${code.toUpperCase()} · ${r.result==='EXPECTED'?'counted':'unexpected — investigate before adjusting stock'}`);setCode('')}}}><div className="scan-input"><ScanLine size={23}/><input autoFocus aria-label="Stock check barcode" placeholder="Scan a piece ID…" value={code} onChange={e=>setCode(e.target.value)}/><button className="btn primary" disabled={busy||!can('check')||!code.trim()}>Count<Plus size={15}/></button></div>{feedback&&<p role="status" className="muted">{feedback}</p>}</form>}{check.status==='OPEN'&&<ScannerInput disabled={busy||!can('check')} onScan={async(code:string)=>{const r=await action('observe',{id:check.id,code});if(r)setFeedback(code+' · '+r.result)}}/>}<Table rows={rows} columns={[{key:'code',label:'Piece / scan'},{key:'holder',label:'Expected custody',render:(p:any)=>display(p.holder||'Not in snapshot')},{key:'condition',label:'Snapshot condition',render:(p:any)=>display(p.condition||'Unknown')},{key:'result',label:'Result',render:(p:any)=><Badge value={p.result}/>}]} exportName={'Stock check · '+check.name}/>{check.status==='OPEN'&&<div className="modal-footer">{closing&&<p className="muted">Close with {missing.length} missing and {unexpected.length} unexpected? Inventory stays unchanged.</p>}<button className="btn primary" disabled={busy||!can('check')} onClick={()=>closing?action('closeCheck',{id:check.id},()=>setClosing(false)):setClosing(true)}>{closing?'Confirm close':'Close stock check'}<Check size={16}/></button></div>}</>}
function ArtisanHistory({artisan,d,date,pname,outstandingPieces,openTransaction}:any){const records=d.transactions.filter((t:any)=>(t.artisan_id===artisan.id||t.type==='ARTIST_TRANSFER'&&JSON.parse(t.snapshot).some((p:any)=>p.from_artisan_id===artisan.id))&&t.status!=='DRAFT'&&['HANDOFF','RETURN','REVERSAL','DISPUTE','ARTIST_TRANSFER','REPRINT_OUT','REPRINT_RECEIVE'].includes(t.type)).sort((a:any,b:any)=>b.created_at.localeCompare(a.created_at));const rows=records.map((t:any)=>{let pieces:any[]=[];try{pieces=JSON.parse(t.snapshot)}catch{}const products=Object.entries(pieces.reduce((acc:any,p:any)=>{const name=p.product_name||pname(p.product_id);acc[name]=(acc[name]||0)+1;return acc},{})).map(([name,count])=>`${name} (${count})`).join(', ');return {...t,pieceRows:pieces,pieces:pieces.length,products:products||'—'}});const total=(type:string)=>rows.filter((r:any)=>r.status==='CONFIRMED'&&(type==='HANDOFF'?['HANDOFF','REPRINT_OUT','ARTIST_TRANSFER'].includes(r.type)&&r.artisan_id===artisan.id:['RETURN','REPRINT_RECEIVE'].includes(r.type)||r.type==='ARTIST_TRANSFER'&&r.artisan_id!==artisan.id)).reduce((sum:number,r:any)=>sum+r.pieces,0);const handoffs=rows.filter((r:any)=>['HANDOFF','ARTIST_TRANSFER','REPRINT_OUT'].includes(r.type)&&r.artisan_id===artisan.id&&r.status==='CONFIRMED');const outstanding=outstandingPieces.map((p:any)=>{const handoff=handoffs.find((t:any)=>t.pieceRows.some((x:any)=>x.id===p.id));const sentAt=handoff?.created_at||p.created_at,days=Math.max(0,Math.floor((Date.now()-new Date(sentAt).getTime())/86400000));return {...p,sentAt,days,handoff}}).sort((a:any,b:any)=>b.days-a.days);const age=(days:number)=>days>14?'aging-danger':days>7?'aging-warning':'aging-current',quantity=(n:number)=>`${n} ${n===1?'saree':'sarees'}`;return <><div className="detail-title"><div><h3>{artisan.name}</h3><p>{artisan.work_type||'Work type not recorded'} · {artisan.address||'Address not recorded'}</p></div><Badge value={artisan.active?'Active':'Archived'}/></div><div className="receipt-stats"><div><small>Total taken for work · lifetime</small><b>{total('HANDOFF')} <small>pieces</small></b></div><div><small>Total returned · lifetime</small><b>{total('RETURN')} <small>pieces</small></b></div><div><small>Outstanding now</small><b>{outstanding.length} <small>pieces</small></b></div><div><small>Movement records</small><b>{records.length}</b></div></div><div className="info-strip"><Clock size={17}/>Each movement shows when and how many sarees were taken or returned. Use View sarees to see every exact Piece Code.</div><Table rows={rows} columns={[{key:'created_at',label:'Taken / returned on',render:(r:any)=>date(r.created_at,true)},{key:'type',label:'Work movement',render:(r:any)=><div className="cell-title">{r.type==='HANDOFF'?`Took ${quantity(r.pieces)} for work`:r.type==='RETURN'?`Returned ${quantity(r.pieces)}`:r.type==='DISPUTE'?`Disputed ${quantity(r.pieces)}`:r.type==='ARTIST_TRANSFER'?`${r.artisan_id===artisan.id?'Received transfer of':'Transferred out'} ${quantity(r.pieces)}`:r.type==='REPRINT_OUT'?`Took ${quantity(r.pieces)} for reprint`:r.type==='REPRINT_RECEIVE'?`Returned ${quantity(r.pieces)} after reprint`:`Reversed ${quantity(r.pieces)}`}<small>{r.number}</small></div>},{key:'products',label:'Products'},{key:'status',label:'Status',render:(r:any)=><Badge value={r.status}/>},{key:'details',label:'Saree codes',render:(r:any)=><button className="text-btn" onClick={()=>openTransaction(r)}>View sarees<ArrowUpRight size={14}/></button>}]} exportName={`${artisan.name} · lifetime records`} empty="No recorded work yet" pageSize={10}/><div className="records-section-heading"><div><h3>Outstanding sarees</h3><p>Exact pieces currently with {artisan.name}, measured from the latest confirmed handoff.</p></div><div className="age-legend"><span className="aging-warning">8–14 days</span><span className="aging-danger">15+ days</span></div></div><Table search={false} rows={outstanding} columns={[{key:'code',label:'Piece code',render:(p:any)=><span className="mono ink">{p.code}</span>},{key:'product_id',label:'Product',render:(p:any)=>pname(p.product_id)},{key:'sentAt',label:'Taken on',render:(p:any)=>date(p.sentAt,true)},{key:'days',label:'Days with artisan',render:(p:any)=><span className={'aging-count '+age(p.days)}>{p.days} {p.days===1?'day':'days'}</span>},{key:'handoff',label:'Handoff details',render:(p:any)=>p.handoff?<button className="text-btn" onClick={()=>openTransaction(p.handoff)}>View sarees<ArrowUpRight size={14}/></button>:'Earlier record'}]} exportName={`${artisan.name} · outstanding sarees`} empty="No sarees are currently outstanding" pageSize={10}/></>}
function TransactionDetail({tx,d,date,aname,can,busy,action,onClose,onPrint}:any){const [reverse,setReverse]=useState(false),[reason,setReason]=useState('');const rows=JSON.parse(tx.snapshot);return <><div className="detail-title"><div><h3 className="mono">{tx.number}</h3><p>{tx.type} · {date(tx.created_at,true)} · {tx.actor}</p></div><Badge value={tx.status}/></div><div className="summary-strip"><div><span>Artist / Ground Staff</span><b>{rows[0]?.ground_staff_name||rows[0]?.artisan_name||aname(tx.artisan_id)}</b></div><div><span>Exact pieces</span><b>{rows.length}</b></div></div>{tx.reason&&<p className="info-strip">{tx.reason}</p>}<Table rows={rows} columns={[{key:'code',label:'Piece ID'},{key:'company_name',label:'Source company',render:(p:any)=>p.company_name||d.companies.find((c:any)=>c.id===p.company_id)?.name},{key:'product_name',label:'Product',render:(p:any)=>p.product_name||d.products.find((c:any)=>c.id===p.product_id)?.name},{key:'lot_number',label:'Original lot',render:(p:any)=>p.lot_number||d.lots.find((c:any)=>c.id===p.lot_id)?.number},{key:'outcome',label:'Outcome',render:(p:any)=>display(p.outcome||'—')},{key:'inspection_reason',label:'Inspection reason'},{key:'from_artisan_name',label:'Sending artist'},{key:'ground_staff_name',label:'Ground Staff'}]} exportName={tx.number}/>{tx.original_id&&<p className="muted">Linked correction of {d.transactions.find((t:any)=>t.id===tx.original_id)?.number||tx.original_id}</p>}{reverse&&<><div className="info-strip"><RotateCcw size={17}/>All {rows.length} pieces must still be in the state left by this transaction. Any later change blocks the entire reversal.</div><Field label="Reversal reason"><textarea rows={3} required value={reason} onChange={e=>setReason(e.target.value)}/></Field></>}<div className="modal-footer spread">{['HANDOFF','RETURN'].includes(tx.type)&&tx.status==='CONFIRMED'&&<button className="btn" disabled={busy||!can('reverse')||reverse&&!reason.trim()} onClick={()=>reverse?action('reverse',{id:tx.id,reason},onClose):setReverse(true)}><RotateCcw size={15}/>{reverse?'Confirm reversal':'Reverse transaction'}</button>}<button className="btn primary" onClick={onPrint}><Printer size={16}/>Print transaction</button></div></>}
function SettingsForm({d,can,action,busy}:any){return <form className="panel settings-panel" onSubmit={e=>{e.preventDefault();action('settings',Object.fromEntries(new FormData(e.currentTarget)))}}><div className="panel-heading"><div><h2>Workspace preferences</h2><p>Business display, label dimensions, and local time.</p></div><ShieldCheck size={20} className="muted"/></div><div className="form-grid"><Field label="Business display name"><input name="business_name" defaultValue={d.settings.business_name||'IMS TARA MAA'} required/></Field><Field label="Business timezone"><input name="timezone" defaultValue={d.settings.timezone||'Asia/Kolkata'} required placeholder="Asia/Kolkata"/></Field><Field label="Label width (mm)"><input type="number" min="30" max="100" name="label_width" defaultValue={d.settings.label_width||50} required/></Field><Field label="Label height (mm)"><input type="number" min="20" max="80" name="label_height" defaultValue={d.settings.label_height||25} required/></Field></div><div className="settings-defaults"><span><CheckCircle2 size={16}/>Code 128 barcodes</span><span><CheckCircle2 size={16}/>Mandatory scan confirmation</span><span><CheckCircle2 size={16}/>UTC event storage</span></div><div className="modal-footer"><button className="btn primary" disabled={busy||!can('settings')}>Save preferences<Check size={16}/></button></div></form>}
function Reports({d,enriched,transactionColumns,date,aname,cname,openTransaction,openPiece}:any){const [kind,setKind]=useState('Movements'),[from,setFrom]=useState(''),[to,setTo]=useState(''),[audit,setAudit]=useState<any[]>([]),[auditError,setAuditError]=useState('');const inRange=(s:string)=>{const day=new Date(s).toLocaleDateString('en-CA',{timeZone:d.settings.timezone||'Asia/Kolkata'});return (!from||day>=from)&&(!to||day<=to)};const tx=d.transactions.filter((t:any)=>inRange(t.created_at));useEffect(()=>{if(kind==='Audit log')fetch('/api/ledger?audit=1').then(r=>r.json()).then((j:any)=>{if(j.error)setAuditError(j.error);else setAudit(j.events||[])}).catch(e=>setAuditError(e.message))},[kind]);const balanceColumns=[{key:'name',label:kind==='Company balances'?'Company':'Artisan'},{key:'total',label:'Registered / outstanding'},{key:'available',label:'Available in house'},{key:'with_artisan',label:'With artisans'},{key:'pending',label:'Pending labels'},{key:'rework',label:'Needs rework'},{key:'damaged',label:'Damaged'}];const group=(list:any[],field:string)=>list.map(a=>{const ps=enriched.filter((p:any)=>p[field]===a.id);return {id:a.id,name:a.name,total:ps.length,available:ps.filter((p:any)=>p.holder==='IN_HOUSE'&&['AVAILABLE','ACCEPTED_WORK'].includes(p.condition)).length,with_artisan:ps.filter((p:any)=>p.holder==='WITH_ARTISAN').length,pending:ps.filter((p:any)=>!p.label_confirmed_at).length,rework:ps.filter((p:any)=>p.condition==='NEEDS_REWORK').length,damaged:ps.filter((p:any)=>p.condition==='DAMAGED').length}});let rows:any[]=tx,columns:any[]=transactionColumns;if(kind==='Company balances'){rows=group(d.companies,'company_id');columns=balanceColumns;}if(kind==='Artisan balances'){rows=d.artisans.map((a:any)=>({id:a.id,name:a.name,issued:tx.filter((t:any)=>t.type==='HANDOFF'&&t.artisan_id===a.id&&t.status==='CONFIRMED').reduce((s:number,t:any)=>s+JSON.parse(t.snapshot).length,0),returned:tx.filter((t:any)=>t.type==='RETURN'&&t.artisan_id===a.id&&t.status==='CONFIRMED').reduce((s:number,t:any)=>s+JSON.parse(t.snapshot).length,0),outstanding:enriched.filter((p:any)=>p.artisan_id===a.id).length}));columns=[{key:'name',label:'Artisan'},{key:'issued',label:'Issued · selected dates'},{key:'returned',label:'Returned · selected dates'},{key:'outstanding',label:'Outstanding · live now'}];}if(kind==='Rework & damage'){rows=enriched.filter((p:any)=>['NEEDS_REWORK','DAMAGED'].includes(p.condition));columns=[{key:'code',label:'Piece ID'},{key:'company',label:'Company'},{key:'product',label:'Product'},{key:'lot',label:'Lot'},{key:'custodian',label:'Current holder'},{key:'condition',label:'Condition',render:(p:any)=><Badge value={p.condition}/>}]};if(kind==='Receipts'){rows=d.lots.filter((l:any)=>inRange(l.received_at)).map((l:any)=>({...l,company:cname(l.company_id),variance:l.stated-l.accepted-l.damaged-l.rejected}));columns=[{key:'number',label:'Lot'},{key:'company',label:'Company'},{key:'stated',label:'Stated'},{key:'accepted',label:'Accepted'},{key:'damaged',label:'Damaged'},{key:'rejected',label:'Rejected'},{key:'variance',label:'Variance'}];}if(kind==='Audit log'){rows=audit.filter((e:any)=>inRange(e.created_at));columns=[{key:'code',label:'Piece ID'},{key:'type',label:'Event'},{key:'actor',label:'Actor'},{key:'created_at',label:'Timestamp',render:(e:any)=>date(e.created_at,true)},{key:'reason',label:'Reason'}];}if(kind==='Stock variance'){rows=d.checks.map((c:any)=>{const expected=JSON.parse(c.expected),observed=d.observations.filter((o:any)=>o.check_id===c.id);return {...c,expected:expected.length,counted:observed.filter((o:any)=>o.result==='EXPECTED').length,missing:expected.filter((p:any)=>!observed.some((o:any)=>o.code===p.code)).length,unexpected:observed.filter((o:any)=>o.result==='UNEXPECTED').length}});columns=[{key:'name',label:'Stock check'},{key:'expected',label:'Expected'},{key:'counted',label:'Counted'},{key:'missing',label:'Missing'},{key:'unexpected',label:'Unexpected'},{key:'status',label:'Status'}];}
return <><PageHeading title="Reports & audit" description="Current balances and historical flows, with exact piece-level records."/><div className="report-options">{['Movements','Company balances','Artisan balances','Receipts','Rework & damage','Stock variance','Audit log'].map(k=><button key={k} className={kind===k?'selected':''} onClick={()=>setKind(k)}>{k}</button>)}</div><section className="panel"><div className="panel-heading"><div><h2>{kind}</h2><p>{['Company balances','Rework & damage','Stock variance'].includes(kind)?'Current snapshot · date filters do not change live balances':'Flow counts include confirmed, non-reversed transactions. All movements remain in the table.'}</p></div>{!['Company balances','Rework & damage','Stock variance'].includes(kind)&&<div className="date-filters"><input aria-label="From date" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><span>to</span><input aria-label="To date" type="date" value={to} onChange={e=>setTo(e.target.value)}/></div>}</div>{auditError&&kind==='Audit log'&&<p role="alert">{auditError}</p>}<Table key={kind} rows={rows} columns={columns} exportName={`${kind} · ${from||'all time'} to ${to||'now'}`} onRow={kind==='Movements'?openTransaction:kind==='Rework & damage'?openPiece:undefined} pageSize={12}/></section>{['Company balances','Artisan balances'].includes(kind)&&<section className="panel margin-top"><div className="panel-heading"><h2>Exact pieces behind the live balance</h2></div><Table rows={kind==='Artisan balances'?enriched.filter((p:any)=>p.holder==='WITH_ARTISAN'):enriched} columns={[{key:'code',label:'Piece ID'},{key:'company',label:'Company'},{key:'product',label:'Product'},{key:'lot',label:'Lot'},{key:'custodian',label:'Current holder'}]} onRow={openPiece} exportName={kind+' exact pieces'}/></section>}</>}

function ArtisanMovements({view,d,action,busy,can}:any){const [mode,setMode]=useState(view==='Handoff'?'handoff':'return');return <><div className="tabs"><button className={mode===(view==='Handoff'?'handoff':'return')?'selected':''} onClick={()=>setMode(view==='Handoff'?'handoff':'return')}>{view==='Handoff'?'Out to Artist':'Artist Delivery'}</button><button className={mode==='dispute'?'selected':''} onClick={()=>setMode('dispute')}>Report dispute</button></div><ScanStation key={mode} mode={mode} d={d} action={action} busy={busy} can={can}/><DisputeLog d={d}/></>}
